mapper.select:
SELECT id, position, direction, display_content AS displayContent, create_time
FROM job_posting WHERE audit_status = 'APPROVED' AND direction = #{direction}
ORDER BY id DESC

SELECT id, position, direction, content, display_content, submitter_id, submitter_ip, submitter_role, create_time
FROM job_posting WHERE audit_status = 'PENDING'
ORDER BY id ASC LIMIT #{offset}, #{limit}

SELECT id, company, position, direction, audit_status, submitter_id, reject_reason, create_time
FROM job_posting

    audit_status = #{status}

ORDER BY id DESC LIMIT #{offset}, #{limit}
